import { useState } from "react";
import styled from "styled-components";
import mq from "./MediaQuery";

const DrawerMenuContainer = styled.div`

    .btnIcon {
        display: block;
        position: absolute;
        right: 20px;
        top: 10px;
        cursor: pointer;
        font-size: 24px;
    }

    .drawer-menu {

        display: none;
        ${mq.maxWidth('xl')`
            display: block;
            position: fixed;
            top: 0;
            right: 0;
            width: 70%;
            height: 100vh;
            z-index: 999;
            background: #fafafa;
            transform: translateX(100%);
            transition: transform 0.3s ease-in-out;
            margin-top: 70px;
        `}
    }

    .drawer-menu.open {
        transform: translateX(0);
    }

    
    .close-btn {
        background: none;
        border: none;
        font-size: 24px;
        cursor: pointer;
        position: absolute;
        right: 15px;
        top: 10px;
    }

    .menu-title {
        display: block;
        width: 100%;
        font-size: 19.2px;
        line-height: 2.9em;
        text-align: left;
        padding-left: 20px;
    }

    hr {
        opacity: 0.3;
        color: #fafafa;
    }

    /* 서브메뉴 스타일 */
    .sub-menu {
        display: block;
        max-height: 5px;
        width: 100%;
        text-align: left;
        background-color: #fff;
        opacity: 0;
        overflow: hidden;
        transform: translateY(-5px);
        transition: max-height 0.5s ease-in-out, opacity 0.5s ease-out, transform 0.4s ease-out;

    
        li {
            display: block;
            position: relative;
            width: 100%;
            padding-left: 30px;
            line-height: 2.8em;
            margin-top: 5px;
        
            hr {
                position: absolute;
                display: block;
                width: 100%;
                left: -10px;
            }
        }
    }
    

    .sub-menu.open {
        background-color: #fff;
        opacity: 1;
        max-height: 300px;
        transform: scaleY(1);
    }
`;

const DrawerMenu = ({ isOpen, toggleDrawer }) => {
    const [activeMenu, setActiveMenu] = useState(false);

    const toggleSubMenu = (index) => {
        setActiveMenu(activeMenu === index ? null : index);
    };

    return (
        <DrawerMenuContainer>
        <div className={`drawer-menu ${isOpen ? "open" : ""}`}>
            <button className="close-btn" onClick={toggleDrawer}></button>
            <ul>
                {[
                    { title: "빽다방", subMenu: ["CEO인사말", "빽다방 소개", "멤버십 / 앱소개", "커피 이야기", "교육 이야기"] },
                    { title: "메뉴", subMenu: ["신메뉴", "커피", "음료", "아이스크림/디저트", "빽스치노"] },
                    { title: "소식", subMenu: ["소식", "이벤트", "친절 우수매장"] },
                    { title: "커뮤니티", subMenu: ["커피 클래스"] },
                    { title: "매장안내", subMenu: ["매장찾기"] },
                    { title: "창업안내", subMenu: ["왜 빽다방인가요?", "창업상담 신청", "창업절차 및 조건", "인테리어"] },
                    { title: "고객의 소리", subMenu: [] }
                ].map((menu, index) => (
                    <li key={index} className="menu-item">
                        <a href="#" className="menu-title" onClick={(e) => {
                            e.preventDefault();
                            toggleSubMenu(index);
                        }}>
                            {menu.title} 
                        </a>
                        <hr />
                        <ul className={`sub-menu ${activeMenu === index ? "open" : ""}`}>
                            {menu.subMenu.map((item, subIndex) => (
                                <li key={subIndex}><a href="#">{item}</a><hr /></li>
                            ))}
                        </ul>
                    </li>
                ))}
            </ul>
        </div>
        </DrawerMenuContainer>
    );
};

export default DrawerMenu;
